import re
import sys

UNICODE_CHARSETS = [
    re.compile(r"^ISO-10646-UCS-[24]$"),
    re.compile(r"^UTF-16"),
    re.compile(r"^UTF-8$"),
    re.compile(r"^UTF-32"),
]

HEADER = """/*
 * This file is part of LibParserUtils.
 * Licensed under the MIT License,
 *                http://www.opensource.org/licenses/mit-license.php
 * Copyright 2010 The NetSurf Project.
 *
 * Note: This file is automatically generated by make-aliases.py
 *
 * Do not edit file file, changes will be overwritten during build.
 */

static parserutils_charset_aliases_canon canonical_charset_names[] = {
"""

ALIAS_STRUCT = """typedef struct {
	uint16_t name_len;
	const char *name;
	parserutils_charset_aliases_canon *canon;
} parserutils_charset_aliases_alias;

static parserutils_charset_aliases_alias charset_aliases[] = {
"""


def simplify(name):
    return re.sub(r"[^a-z0-9]", "", name.lower())


def generate(source):
    charsets = {}
    with open(source, encoding="utf-8") as f:
        for line in f:
            line = line.rstrip("\n")
            if line.startswith("#") or line == "":
                continue
            elements = line.split()
            charsets[elements[0]] = (elements[1], elements[2:])

    out = [HEADER]
    aliases = {}
    unicode = []
    for index, canon in enumerate(sorted(charsets)):
        mibenum, names = charsets[canon]
        out.append('\t{ %s, %d, "%s" },\n' % (mibenum, len(canon), canon))
        if any(r.search(canon) for r in UNICODE_CHARSETS):
            unicode.append("((x) == %s)" % mibenum)
        aliases[simplify(canon)] = index
        for name in names:
            aliases[simplify(name)] = index
    out.append("};\n\nstatic const uint16_t charset_aliases_canon_count = %d;\n\n" % len(charsets))
    out.append(ALIAS_STRUCT)
    for alias in sorted(aliases):
        out.append('\t{ %d, "%s", &canonical_charset_names[%d] },\n' % (len(alias), alias, aliases[alias]))
    out.append("};\n\n")
    out.append("static const uint16_t charset_aliases_count = %d;\n\n" % len(aliases))
    out.append("#define MIBENUM_IS_UNICODE(x) (%s)\n" % " || ".join(unicode))
    return "".join(out)


def write_if_changed(path, text):
    try:
        with open(path, encoding="utf-8") as f:
            if f.read() == text:
                return
    except OSError:
        pass
    with open(path, "w", encoding="utf-8") as f:
        f.write(text)


if __name__ == "__main__":
    source = sys.argv[1] if len(sys.argv) > 1 else "build/Aliases"
    target = sys.argv[2] if len(sys.argv) > 2 else "src/charset/aliases.inc"
    write_if_changed(target, generate(source))
